    let addr = serverListenAddr(options);
    if (addr.endsWith(":0")) {
      const port = await reservePort();
      addr = `127.0.0.1:${port}`;
    }
    const port = addr.split(":").pop();
    const localServerURL = `http://127.0.0.1:${port}`;
